1	// Acceptance test for the change request:
2	//   "I call these jobs, not projects. Please use that word everywhere."
3	//
4	// The feature the app calls "projects" must be presented to the user as "jobs" EVERYWHERE the word
5	// is shown: the nav link, the list page title and its empty state, the add form's button, the
6	// detail page title, the dashboard figure, a client's count label, the client's own list toggle and
7	// empty state, the all-invoices column header, and the global search (its placeholder and results
8	// column). After this change none of these surfaces should read "project"/"projects" any more.
9	//
10	// This is a WORDING change only — the data-testid anchors are the app's public contract and DO NOT
11	// change (nav-projects, projects-page, project-detail-page, dashboard-projects-count,
12	// client-projects-count, client-projects-show-all, client-projects-empty, projects-empty,
13	// project-form-submit, all-invoices-table, search-projects all keep their names). So every
14	// assertion still reaches its target THROUGH a data-testid; what is checked is the human-readable
15	// text that testid-anchored element renders.
16	//
17	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
18	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId } and
19	// `invoices` honours { id, amount, projectId, status }. Seeded names deliberately avoid the word
20	// "project", so a page-level "no longer says project" assertion can only be tripped by the chrome
21	// this change is meant to rename, not by seeded data.
22	import { test, expect, type Page } from '@playwright/test';
23	import { resetAndSeed } from '../support/seed';
24	
25	test.describe('The feature is called "jobs", not "projects"', () => {
26	  test('the nav link calls the section Jobs', async ({ page }) => {
27	    await resetAndSeed({ clients: [], projects: [] });
28	
29	    await page.goto('/');
30	    await expect(page.getByTestId('app-nav')).toBeVisible();
31	
32	    // The section's one nav link (its anchor is unchanged) now reads "Jobs".
33	    const nav = page.getByTestId('nav-projects');
34	    await expect(nav).toBeVisible();
35	    await expect(nav).toHaveText('Jobs');
36	  });
37	
38	  test('the list page is titled Jobs, empties with "No jobs yet.", and adds a Job', async ({
39	    page,
40	  }) => {
41	    // A client exists (pickable in the add form) but there are no jobs yet.
42	    await resetAndSeed({
43	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
44	      projects: [],
45	    });
46	
47	    await page.goto('/projects');
48	    const listPage = page.getByTestId('projects-page');
49	    await expect(listPage).toBeVisible();
50	
51	    // Title reads "Jobs"; the old "Projects" title is gone.
52	    await expect(listPage.getByRole('heading', { name: 'Jobs', exact: true })).toBeVisible();
53	    await expect(listPage.getByRole('heading', { name: 'Projects', exact: true })).toHaveCount(0);
54	
55	    // Empty state and add button both use the new word.
56	    await expect(page.getByTestId('projects-empty')).toHaveText('No jobs yet.');
57	    await expect(page.getByTestId('project-form-submit')).toHaveText('Add job');
58	
59	    // Nowhere on the page (with no seeded job names to confuse it) does the old word survive —
60	    // "roject" catches Project/Projects/project/projects in any casing.
61	    await expect(listPage).not.toContainText('roject');
62	  });
63	
64	  test("a job's detail page is titled Job, not Project", async ({ page }) => {
65	    await resetAndSeed({
66	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
67	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
68	    });
69	
70	    await page.goto('/projects/1');
71	    const detail = page.getByTestId('project-detail-page');
72	    await expect(detail).toBeVisible();
73	
74	    // The detail page is titled "Job"; the old "Project" title is gone.
75	    await expect(detail.getByRole('heading', { name: 'Job', exact: true })).toBeVisible();
76	    await expect(detail.getByRole('heading', { name: 'Project', exact: true })).toHaveCount(0);
77	  });
78	
79	  test('the dashboard figure is labelled Jobs, not Projects', async ({ page }) => {
80	    await resetAndSeed({
81	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
82	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
83	    });
84	
85	    await page.goto('/dashboard');
86	    const summary = page.getByTestId('dashboard');
87	    await expect(summary).toBeVisible();
88	
89	    // The count is unchanged behaviour; only its LABEL is renamed. The figure's anchor stays
90	    // `dashboard-projects-count`, and the visible label beside it now reads "Jobs".
91	    await expect(summary.getByText('Jobs', { exact: true })).toBeVisible();
92	    await expect(summary).not.toContainText('Project');
93	    await expect(page.getByTestId('dashboard-projects-count')).toBeVisible();
94	  });
95	
96	  test("a client's page labels the count Jobs and uses 'jobs' in its own list", async ({ page }) => {
97	    // A client with NO jobs: exercises the count label, the "show all" toggle and the empty state
98	    // all at once.
99	    await resetAndSeed({
100	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
101	      projects: [],
102	    });
103	
104	    await page.goto('/clients/1');
105	    await expect(page.getByTestId('client-detail-page')).toBeVisible();
106	
107	    // The at-a-glance counts label the figure "Jobs" (its anchor is unchanged).
108	    const counts = page.getByTestId('client-counts');
109	    await expect(counts).toBeVisible();
110	    await expect(counts.getByText('Jobs', { exact: true })).toBeVisible();
111	    await expect(counts).not.toContainText('Project');
112	    await expect(page.getByTestId('client-projects-count')).toBeVisible();
113	
114	    // The client's own list: the toggle and the empty state both use the new word.
115	    await expect(page.getByTestId('client-projects-show-all')).toHaveText('Show all jobs');
116	    await expect(page.getByTestId('client-projects-empty')).toHaveText(
117	      'No jobs for this client yet.',
118	    );
119	  });
120	
121	  test('the all-invoices table heads the column Job, not Project', async ({ page }) => {
122	    await resetAndSeed({
123	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
124	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
125	      invoices: [{ id: 1, amount: 100, projectId: 1, status: 'SENT' }],
126	    });
127	
128	    await page.goto('/invoices');
129	    const table = page.getByTestId('all-invoices-table');
130	    await expect(table).toBeVisible();
131	
132	    // The column that names which job each invoice is for is headed "Job"; the old "Project" header
133	    // is gone. (The seeded job name "Website Redesign" never contains the word, so the header is the
134	    // only place the column word could appear.)
135	    await expect(table.getByRole('columnheader', { name: 'Job', exact: true })).toBeVisible();
136	    await expect(table.getByRole('columnheader', { name: 'Project', exact: true })).toHaveCount(0);
137	  });
138	
139	  test('global search uses "jobs" in its placeholder and its results column', async ({ page }) => {
140	    await resetAndSeed({ clients: [], projects: [] });
141	
142	    await page.goto('/');
143	
144	    // The one search box's placeholder now says "jobs".
145	    await expect(page.getByTestId('global-search')).toHaveAttribute(
146	      'placeholder',
147	      'Search clients and jobs',
148	    );
149	
150	    // Its results grouping heads the column "Job"; the old "Project" header is gone. The grouping's
151	    // anchor (search-projects) is unchanged.
152	    const jobHits = page.getByTestId('search-projects');
153	    await expect(jobHits.getByRole('columnheader', { name: 'Job', exact: true })).toBeVisible();
154	    await expect(jobHits.getByRole('columnheader', { name: 'Project', exact: true })).toHaveCount(0);
155	  });
156	});
